#include <bits/stdc++.h>
using namespace std;

int maxMinDist = INT_MIN;
int findAllSubsequences(vector<int>& nums, int currIndex, int prevIndex, int minDistTillNow, int m, vector<vector<vector<int>>>& dp){


  if(currIndex >= nums.size()){
    if(m == 0)
      maxMinDist = max(maxMinDist, minDistTillNow); 
    return minDistTillNow;
  }
  if(m == 0){
      maxMinDist = max(maxMinDist, minDistTillNow);
      return minDistTillNow;
  }
//   if(prevIndex != -1 && dp[currIndex][prevIndex][m] != -1){
//     return dp[currIndex][prevIndex][m];
//   }
  int noTake = findAllSubsequences(nums, currIndex+1, prevIndex, minDistTillNow, m, dp);
  if(prevIndex != -1){
    int dist = nums[currIndex] - nums[prevIndex];
    minDistTillNow = min(minDistTillNow, dist);
  }
  int take = findAllSubsequences(nums, currIndex+1, currIndex, minDistTillNow, m - 1, dp);

//   cout<<"prevIndex-> "<<prevIndex<<endl;
  if(prevIndex != -1){
      return dp[currIndex][prevIndex][m] = max(take, noTake);
  }
  return max(take, noTake);
}

